import json

def transform(grid):
    background = grid[0][0]
    h, w = len(grid), len(grid[0])

    # Find top shape (bounding box of non-background, non-0 cells)
    top_r_min, top_r_max, top_c_min, top_c_max = h, -1, w, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in [background, 0]:
                top_r_min = min(top_r_min, r)
                top_r_max = max(top_r_max, r)
                top_c_min = min(top_c_min, c)
                top_c_max = max(top_c_max, c)

    # Find bottom shape (bounding box of 0s)
    bot_r_min, bot_r_max, bot_c_min, bot_c_max = h, -1, w, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                bot_r_min = min(bot_r_min, r)
                bot_r_max = max(bot_r_max, r)
                bot_c_min = min(bot_c_min, c)
                bot_c_max = max(bot_c_max, c)

    # Extract subgrid from columns (top_c_min to top_c_min + width for bottom)
    # The pattern width = width of sampled grid for bottom (usually 4)
    subgrid = [grid[r][top_c_min:top_c_min+1] for r in range(top_r_min, top_r_max+1)]

    # Create output, filled with background
    output = [[background for _ in range(w)] for _ in range(h)]

    # Copy top shape
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in [background, 0]:
                output[r][c] = grid[r][c]

    # Replace 0s with pattern (using 1)
    # The width of the bottom grid determines which columns to sample
    bot_width = bot_c_max - bot_c_min + 1

    for r in range(bot_r_min, bot_r_max + 1):
        for c in range(bot_c_min, bot_c_max + 1):
            output[r][c] = 1

    return output

